from __future__ import annotations
import argparse,json
from pathlib import Path

def main():
    ap=argparse.ArgumentParser(); ap.add_argument('--split-a',required=True); ap.add_argument('--split-b',required=True); ap.add_argument('--reservation-report',required=True); ap.add_argument('--fit-report',required=True); ap.add_argument('--output',required=True); a=ap.parse_args()
    A=json.load(open(a.split_a)); B=json.load(open(a.split_b)); C=json.load(open(a.reservation_report)); F=json.load(open(a.fit_report))
    eng=bool(A.get('engineering_valid') and B.get('engineering_valid')); train=bool(F.get('train_gate_pass')); cal=bool(C.get('calibration_total_scene_count')==500 and int(C.get('selected_policy_proposal_count',0))>=64); both=bool(eng and train and cal and A.get('full_split_pass') and B.get('full_split_pass'))
    rep={'audit':'v64_3_36_eaf_icer_sgrr_double_fresh_screen','engineering_valid_both':eng,'train_nested_reservation_gate_pass':train,'independent_CAL500_reservation_fit_valid':cal,'double_fresh_promotion_pass':both,'scientific_conclusion':'SGRR_reproduces_on_double_fresh' if both else ('engineering_invalid_stop' if not eng else 'SGRR_not_promoted_current_frozen_mechanism_fails_at_least_one_independent_gate_or_block'),'next_action':'freeze_and_run_one_independent_full_validation_reproduction' if both else 'STOP_do_not_pool_AB_or_sweep_thresholds_use_clean_basepoint_vs_selection_geometry_reservation_failure_slice_for_next_mechanism','train_fit':F,'independent_reservation_fit':C,'split_A':A,'split_B':B,'protocol':'Exact V35 failure prerequisite -> nested TRAIN frozen V34 RSMR ordering -> independent-fold basepoint reservation diagnostic + selection-geometry reservation main, both monotone common-subtraction vetoes -> if TRAIN passes, independent CAL500 fits the two reservation heads on frozen RSMR selected-policy overprediction -> untouched A500/B500. No reservation arm can re-rank challengers or create a new proposal.'}
    Path(a.output).write_text(json.dumps(rep,indent=2,sort_keys=True)+'\n'); print(json.dumps({'pass':both,'engineering':eng,'train':train,'calibration':cal,'conclusion':rep['scientific_conclusion']},sort_keys=True))
if __name__=='__main__': main()
